use std::process::ExitCode;
use std::sync::mpsc;

use wgpu::util::DeviceExt;

const WORKGROUP: u32 = 16;

const SHADER: &str = r#"
struct Dims {
    width: u32,
    height: u32,
}

@group(0) @binding(0) var<uniform> dims: Dims;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(16, 16)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    let x = id.x;
    let y = id.y;
    if (x >= dims.width || y >= dims.height) {
        return;
    }

    var neighbours = 0u;
    for (var dy = -1; dy <= 1; dy++) {
        for (var dx = -1; dx <= 1; dx++) {
            if (dx == 0 && dy == 0) {
                continue;
            }
            let nx = i32(x) + dx;
            let ny = i32(y) + dy;
            if (nx >= 0 && ny >= 0 && nx < i32(dims.width) && ny < i32(dims.height)) {
                neighbours += src[u32(ny) * dims.width + u32(nx)];
            }
        }
    }

    let index = y * dims.width + x;
    var next = 0u;
    if (src[index] == 1u) {
        if (neighbours == 2u || neighbours == 3u) {
            next = 1u;
        }
    } else if (neighbours == 3u) {
        next = 1u;
    }
    dst[index] = next;
}
"#;

struct Grid {
    width: u32,
    height: u32,
    generations: u32,
    cells: Vec<u32>,
}

fn parse(text: &str) -> Result<Grid, String> {
    let mut rest = text;
    let mut header = [0u32; 3];
    for slot in header.iter_mut() {
        let trimmed = rest.trim_start();
        let end = trimmed
            .find(char::is_whitespace)
            .unwrap_or(trimmed.len());
        let token = &trimmed[..end];
        *slot = token
            .parse()
            .map_err(|_| format!("bad header value {token:?}"))?;
        rest = &trimmed[end..];
    }
    let [width, height, generations] = header;
    if !(1..=512).contains(&width) || !(1..=512).contains(&height) {
        return Err(format!("width and height must be 1..=512, got {width} x {height}"));
    }
    if generations > 1000 {
        return Err(format!("generations must be 0..=1000, got {generations}"));
    }

    let mut cells = Vec::with_capacity((width * height) as usize);
    for ch in rest.chars().filter(|c| !c.is_whitespace()) {
        match ch {
            '0' => cells.push(0),
            '1' => cells.push(1),
            other => return Err(format!("cell must be 0 or 1, got {other:?}")),
        }
    }
    let expected = (width * height) as usize;
    if cells.len() != expected {
        return Err(format!("expected {expected} cells, found {}", cells.len()));
    }

    Ok(Grid {
        width,
        height,
        generations,
        cells,
    })
}

fn run_gpu(grid: &Grid) -> Result<Vec<u32>, String> {
    pollster::block_on(run_gpu_async(grid))
}

async fn run_gpu_async(grid: &Grid) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::default();
    let adapter = instance
        .request_adapter(&wgpu::RequestAdapterOptions {
            power_preference: wgpu::PowerPreference::HighPerformance,
            ..Default::default()
        })
        .await
        .map_err(|e| format!("no GPU adapter: {e}"))?;
    let (device, queue) = adapter
        .request_device(&wgpu::DeviceDescriptor::default())
        .await
        .map_err(|e| format!("no GPU device: {e}"))?;

    let size = (grid.width as u64) * (grid.height as u64) * 4;
    let storage = wgpu::BufferUsages::STORAGE
        | wgpu::BufferUsages::COPY_SRC
        | wgpu::BufferUsages::COPY_DST;

    let buffer_a = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("cells A"),
        contents: bytemuck::cast_slice(&grid.cells),
        usage: storage,
    });
    let buffer_b = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("cells B"),
        size,
        usage: storage,
        mapped_at_creation: false,
    });
    let dims = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("dims"),
        contents: bytemuck::cast_slice(&[grid.width, grid.height]),
        usage: wgpu::BufferUsages::UNIFORM,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("life"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("life step"),
        layout: None,
        module: &module,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });

    let layout = pipeline.get_bind_group_layout(0);
    let bind = |src: &wgpu::Buffer, dst: &wgpu::Buffer| {
        device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: None,
            layout: &layout,
            entries: &[
                wgpu::BindGroupEntry {
                    binding: 0,
                    resource: dims.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 1,
                    resource: src.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 2,
                    resource: dst.as_entire_binding(),
                },
            ],
        })
    };
    // Generation k reads from `even` when k is even and from `odd` when k is odd.
    let even = bind(&buffer_a, &buffer_b);
    let odd = bind(&buffer_b, &buffer_a);

    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor::default());
    {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor::default());
        pass.set_pipeline(&pipeline);
        let groups_x = grid.width.div_ceil(WORKGROUP);
        let groups_y = grid.height.div_ceil(WORKGROUP);
        for generation in 0..grid.generations {
            let bind_group = if generation % 2 == 0 { &even } else { &odd };
            pass.set_bind_group(0, bind_group, &[]);
            pass.dispatch_workgroups(groups_x, groups_y, 1);
        }
    }

    // After `generations` steps the newest state is in B when the count is odd.
    let result = if grid.generations % 2 == 0 {
        &buffer_a
    } else {
        &buffer_b
    };
    let staging = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    encoder.copy_buffer_to_buffer(result, 0, &staging, 0, size);
    queue.submit(Some(encoder.finish()));

    let (sender, receiver) = mpsc::channel();
    staging.slice(..).map_async(wgpu::MapMode::Read, move |r| {
        let _ = sender.send(r);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("GPU poll failed: {e}"))?;
    receiver
        .recv()
        .map_err(|e| format!("readback channel closed: {e}"))?
        .map_err(|e| format!("readback failed: {e}"))?;

    let data = staging.slice(..).get_mapped_range();
    let cells: Vec<u32> = bytemuck::cast_slice(&data).to_vec();
    drop(data);
    staging.unmap();
    Ok(cells)
}

fn run(path: &str) -> Result<(), String> {
    let text = std::fs::read_to_string(path).map_err(|e| format!("cannot read {path}: {e}"))?;
    let grid = parse(&text)?;

    let cells = if grid.generations == 0 {
        grid.cells.clone()
    } else {
        run_gpu(&grid)?
    };

    let width = grid.width as usize;
    let mut out = String::with_capacity(cells.len() * 2 + grid.height as usize);
    let mut alive = 0usize;
    for row in cells.chunks(width) {
        for (i, &cell) in row.iter().enumerate() {
            if i > 0 {
                out.push(' ');
            }
            out.push(if cell == 1 { '1' } else { '0' });
            alive += cell as usize;
        }
        out.push('\n');
    }
    out.push_str(&format!("ALIVE {alive}\n"));

    use std::io::Write;
    std::io::stdout()
        .lock()
        .write_all(out.as_bytes())
        .map_err(|e| format!("cannot write stdout: {e}"))
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().collect();
    let Some(path) = args.get(1) else {
        eprintln!("usage: {} <grid-file>", args.first().map_or("life", String::as_str));
        return ExitCode::from(2);
    };
    match run(path) {
        Ok(()) => ExitCode::SUCCESS,
        Err(message) => {
            eprintln!("error: {message}");
            ExitCode::FAILURE
        }
    }
}

